// ─── File: NPlusOneDemo.java ───
// Runnable demo showing N+1 across the network and two fixes.
// Multiple top-level package-private classes simulate a real multi-file project.
package com.bank.portfolio.demo;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.HashMap;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Semaphore;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.*;

public class NPlusOneDemo {

    private static final Logger log = Logger.getLogger("PortfolioDashboard");

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new BankLogFormatter());
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        // Build a portfolio of account IDs (simulating a large relationship-manager book).
        List<String> accountIds = new ArrayList<>();
        accountIds.add("SAV2001");  // Rajesh
        accountIds.add("CUR3001");  // Priya
        for (int i = 1; i <= 8; i++) accountIds.add("ACC" + (4000 + i));

        BalanceServiceClient client = new BalanceServiceClient();
        PortfolioService service = new PortfolioService(client, 10);

        log.info("=== Approach 1: NAIVE (N+1 across the network) ===");
        client.resetCounter();
        long t1 = System.currentTimeMillis();
        List<Account> naive = service.loadNaive(accountIds);
        long e1 = System.currentTimeMillis() - t1;
        log.info(() -> "Naive calls=" + client.getCallCount() + " time=" + e1 + "ms accounts=" + naive.size());

        log.info("=== Approach 2: BULK (one aggregated call) ===");
        client.resetCounter();
        long t2 = System.currentTimeMillis();
        List<Account> bulk = service.loadBulk(accountIds);
        long e2 = System.currentTimeMillis() - t2;
        log.info(() -> "Bulk calls=" + client.getCallCount() + " time=" + e2 + "ms accounts=" + bulk.size());

        log.info("=== Approach 3: PARALLEL fan-out (bounded concurrency) ===");
        client.resetCounter();
        long t3 = System.currentTimeMillis();
        List<Account> par = service.loadParallel(accountIds);
        long e3 = System.currentTimeMillis() - t3;
        log.info(() -> "Parallel calls=" + client.getCallCount() + " time=" + e3 + "ms accounts=" + par.size());

        service.shutdown();
    }
}

// ─── Would be in model/Account.java ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;

    Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
    }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
    void setBalance(BigDecimal balance) { this.balance = balance; }
}

// ─── Would be in client/BalanceServiceClient.java ───
// Simulates the remote Balance Service. Each call adds latency and increments a counter.
class BalanceServiceClient {
    private static final Logger log = Logger.getLogger("PortfolioDashboard");
    private final AtomicInteger callCount = new AtomicInteger(0);

    // One remote call for one account id (the +N per-item endpoint).
    BigDecimal getBalance(String accountId) {
        callCount.incrementAndGet();
        sleep(30); // simulate 30ms network round trip
        log.fine(() -> "remote getBalance(" + accountId + ")");
        return balanceFor(accountId);
    }

    // One remote call for many account ids (the bulk endpoint).
    Map<String, BigDecimal> getBalancesBulk(List<String> ids) {
        callCount.incrementAndGet();
        sleep(40); // one slightly larger call instead of N small ones
        Map<String, BigDecimal> out = new HashMap<>();
        for (String id : ids) out.put(id, balanceFor(id));
        log.fine(() -> "remote getBalancesBulk size=" + ids.size());
        return out;
    }

    private BigDecimal balanceFor(String id) {
        if (id.equals("SAV2001")) return new BigDecimal("1000000.00");
        if (id.equals("CUR3001")) return new BigDecimal("250000.00");
        return new BigDecimal("75000.00");
    }

    int getCallCount() { return callCount.get(); }
    void resetCounter() { callCount.set(0); }
    private void sleep(long ms) { try { Thread.sleep(ms); } catch (InterruptedException e) { Thread.currentThread().interrupt(); } }
}

// ─── Would be in service/PortfolioService.java ───
class PortfolioService {
    private static final Logger log = Logger.getLogger("PortfolioDashboard");
    private final BalanceServiceClient client;
    private final ExecutorService pool;
    private final int concurrency;

    PortfolioService(BalanceServiceClient client, int concurrency) {
        this.client = client;
        this.concurrency = concurrency;
        this.pool = Executors.newFixedThreadPool(concurrency);
    }

    // ANTI-PATTERN: 1 list + N per-item remote calls = N+1.
    List<Account> loadNaive(List<String> ids) {
        List<Account> accounts = new ArrayList<>();
        for (String id : ids) {
            BigDecimal bal = client.getBalance(id); // one network call PER account
            accounts.add(new Account(id, nameFor(id), bal));
        }
        return accounts;
    }

    // FIX 1: a single bulk call collapses N+1 into 1.
    List<Account> loadBulk(List<String> ids) {
        Map<String, BigDecimal> balances = client.getBalancesBulk(ids); // ONE call
        List<Account> accounts = new ArrayList<>();
        for (String id : ids) accounts.add(new Account(id, nameFor(id), balances.get(id)));
        return accounts;
    }

    // FIX 2: bounded parallel fan-out when only a per-item endpoint exists.
    List<Account> loadParallel(List<String> ids) {
        Semaphore gate = new Semaphore(concurrency); // bound in-flight calls
        List<CompletableFuture<Account>> futures = new ArrayList<>();
        for (String id : ids) {
            futures.add(CompletableFuture.supplyAsync(() -> {
                try {
                    gate.acquire();
                    return new Account(id, nameFor(id), client.getBalance(id));
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    throw new RuntimeException(e);
                } finally {
                    gate.release();
                }
            }, pool));
        }
        List<Account> accounts = new ArrayList<>();
        for (CompletableFuture<Account> f : futures) accounts.add(f.join());
        return accounts;
    }

    private String nameFor(String id) {
        if (id.equals("SAV2001")) return "Rajesh Kumar";
        if (id.equals("CUR3001")) return "Priya Sharma";
        return "Account " + id;
    }

    void shutdown() { pool.shutdown(); }
}

